1	import { db } from "./db";
2	import { ovh, ovhApi, ovhConfigured } from "./ovh";
3	import { SANDBOX, sandboxIp, sandboxMac } from "./sandbox";
4	
5	const SERVER = process.env.OVH_SERVER_NAME ?? "ns5002569.ip-51-79-162.net";
6	/** Monthly price the customer pays for a dedicated IPv4 (OVH cost ~$2.39 + margin). */
7	export const DEDICATED_IP_PRICE_CENTS = Number(process.env.DEDICATED_IP_PRICE_CENTS ?? 399);
8	/** Keep this many spare IPs in the pool; auto-order/release aims to stay near it. */
9	export const DEDICATED_IP_BUFFER = Number(process.env.DEDICATED_IP_BUFFER ?? 2);
10	
11	/** OVH failover gateway = the host's /24 gateway (…​.254). */
12	export function ovhGateway(): string {
13	  const ip = process.env.PUBLIC_IP ?? "51.79.162.96";
14	  const parts = ip.split(".");
15	  return `${parts[0]}.${parts[1]}.${parts[2]}.254`;
16	}
17	
18	/**
19	 * Pull additional/failover IPv4 addresses routed to our server from OVH and
20	 * upsert them into the pool. The host's own primary IP is never poolable.
21	 */
22	export async function syncDedicatedIpPool(): Promise<{ imported: number; total: number }> {
23	  if (SANDBOX) return { imported: 0, total: 0 };
24	  if (!ovhConfigured()) return { imported: 0, total: 0 };
25	  const primary = process.env.PUBLIC_IP;
26	  const blocks: string[] = await ovhApi.ips();
27	  let imported = 0;
28	  for (const block of blocks) {
29	    if (block.includes(":")) continue; // IPv6 handled separately
30	    let info: any;
31	    try {
32	      info = await ovhApi.ipInfo(block);
33	    } catch {
34	      continue;
35	    }
36	    if (info?.routedTo?.serviceName !== SERVER) continue;
37	    if (info?.type !== "failover" && info?.type !== "additional") continue; // exclude the primary "dedicated" host IP
38	    // A /32 block is a single usable IP == the block minus the mask.
39	    const address = block.split("/")[0];
40	    if (address === primary) continue;
41	    const existing = await db.dedicatedIp.findUnique({ where: { address } });
42	    if (!existing) {
43	      await db.dedicatedIp.create({ data: { address, ovhBlock: block, status: "FREE" } });
44	      imported++;
45	    }
46	  }
47	  const total = await db.dedicatedIp.count();
48	  return { imported, total };
49	}
50	
51	export async function freeCount(): Promise<number> {
52	  return db.dedicatedIp.count({ where: { status: "FREE" } });
53	}
54	
55	/** Find the OVH Virtual MAC currently bound to an IP, if any. */
56	async function findVirtualMacForIp(address: string): Promise<string | null> {
57	  const macs: string[] = await ovh("GET", `/dedicated/server/${SERVER}/virtualMac`).catch(() => []);
58	  for (const m of macs) {
59	    const ips: string[] = await ovh(
60	      "GET",
61	      `/dedicated/server/${SERVER}/virtualMac/${m}/virtualAddress`
62	    ).catch(() => []);
63	    if (ips.includes(address)) return m;
64	  }
65	  return null;
66	}
67	
68	/**
69	 * Claim a free IP for a server and create its OVH Virtual MAC so the VM can use it.
70	 * Returns the address + virtualMac + gateway, or null if none available.
71	 */
72	export async function allocateDedicatedIp(
73	  serverId: string,
74	  vmid: number
75	): Promise<{ address: string; virtualMac: string; gateway: string } | null> {
76	  if (SANDBOX) {
77	    // Hand out a synthetic dedicated IP without any OVH call or pool mutation.
78	    return { address: sandboxIp(vmid), virtualMac: sandboxMac(vmid), gateway: "198.51.100.254" };
79	  }
80	  if (!ovhConfigured()) return null;
81	  // Atomically claim a FREE ip
82	  const claim = await db.$transaction(async (tx) => {
83	    const ip = await tx.dedicatedIp.findFirst({ where: { status: "FREE" }, orderBy: { createdAt: "asc" } });
84	    if (!ip) return null;
85	    await tx.dedicatedIp.update({ where: { id: ip.id }, data: { status: "PENDING", serverId } });
86	    return ip;
87	  });
88	  if (!claim) return null;
89	
90	  try {
91	    // Reuse an existing vMAC for this IP if one is already bound; else create one.
92	    let mac = await findVirtualMacForIp(claim.address);
93	    if (!mac) {
94	      // Creation is asynchronous (returns a task) — kick it off then poll.
95	      await ovhApi.createVirtualMac(SERVER, claim.address, `nxeon-${vmid}`);
96	      for (let i = 0; i < 40 && !mac; i++) {
97	        await new Promise((r) => setTimeout(r, 3000));
98	        mac = await findVirtualMacForIp(claim.address);
99	      }
100	    }
101	    if (!mac) throw new Error("Virtual MAC not bound after creation (OVH task still pending)");
102	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "ASSIGNED", virtualMac: mac } });
103	    return { address: claim.address, virtualMac: mac, gateway: ovhGateway() };
104	  } catch (e) {
105	    // Roll the claim back to FREE on failure
106	    await db.dedicatedIp.update({ where: { id: claim.id }, data: { status: "FREE", serverId: null, virtualMac: null } });
107	    throw e;
108	  }
109	}
110	
111	/** Release a server's dedicated IP back to the pool (deletes the OVH Virtual MAC). */
112	export async function releaseDedicatedIp(serverId: string): Promise<void> {
113	  if (SANDBOX) return;
114	  const ip = await db.dedicatedIp.findUnique({ where: { serverId } });
115	  if (!ip) return;
116	  if (ovhConfigured() && ip.virtualMac) {
117	    try {
118	      // Remove the IP from the vMAC, then delete the vMAC.
119	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}/virtualAddress/${ip.address}`).catch(() => {});
120	      await ovh("DELETE", `/dedicated/server/${SERVER}/virtualMac/${ip.virtualMac}`).catch(() => {});
121	    } catch {
122	      /* best-effort */
123	    }
124	  }
125	  await db.dedicatedIp.update({
126	    where: { id: ip.id },
127	    data: { status: "FREE", serverId: null, virtualMac: null },
128	  });
129	}
130	
131	/** Set reverse DNS (PTR) for a dedicated IP. */
132	export async function setDedicatedReverse(address: string, reverse: string): Promise<void> {
133	  if (!ovhConfigured()) return;
134	  await ovhApi.setReverse(`${address}/32`, address, reverse);
135	  await db.dedicatedIp.updateMany({ where: { address }, data: { reverse } });
136	}
