function roadmapDoneItems(): string[] {
  try {
    const md = readFileSync("/opt/nxeon/ROADMAP.md", "utf8");
    const items = md
      .split("\n")
      .filter((l) => l.trim().startsWith("- [x]"))
      .map((l) => l.trim().replace(/^- \[x\]\s*/, ""));
    return items.slice(-5).reverse();
  } catch {
    return [];
  }
}

